package org.jfree.chart.imagemap;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StandardToolTipTagFragmentGenerator.generateToolTipFragment
 */
public class StandardToolTipTagFragmentGenerator_generateToolTipFragment_TriageGen0Test {

    private StandardToolTipTagFragmentGenerator generator;

    @Before
    public void setUp() {
        generator = new StandardToolTipTagFragmentGenerator();
    }

    @Test
    public void testGenerateToolTipFragment_withNormalText() {
        String input = "Hello World";
        String expected = " title=\"Hello World\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tool tip fragment should be correctly formatted with the provided text.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withEmptyString() {
        String input = "";
        String expected = " title=\"\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tool tip fragment should handle empty strings correctly.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withNull() {
        // In Java, concatenating null to a String results in the literal "null"
        String input = null;
        String expected = " title=\"null\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tool tip fragment should handle null by converting it to the string 'null'.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withSpecialCharacters() {
        String input = "Text with 'quotes' and \"double quotes\"";
        String expected = " title=\"Text with 'quotes' and \"double quotes\"\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tool tip fragment should preserve special characters within the string.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withWhitespace() {
        String input = "   ";
        String expected = " title=\"   \" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tool tip fragment should preserve whitespace.", expected, actual);
    }
}
